import{_ as o,l as r,o as e,c as i,v as t,p as n,x as l,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"数据中心 Clos / 胖树","description":"","frontmatter":{"title":"数据中心 Clos / 胖树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/datacenter-clos.md","filePath":"cs/datacenter-clos.md","lastUpdated":1789023840000}'),h={name:"cs/datacenter-clos.md"};function C(P,a,_,m,u,E){const s=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="数据中心-clos-胖树" tabindex="-1">数据中心 Clos / 胖树 <a class="header-anchor" href="#数据中心-clos-胖树" aria-label="Permalink to &quot;数据中心 Clos / 胖树&quot;">​</a></h1><div class="epigraph"><p>叶子–脊线全互联把东西向带宽做成多级 Clos；ECMP 把流洒在多条等代价边上，取代大二层生成树。</p><footer>—— 据 Clos, A Study of Non-blocking Switching Networks, BSTJ 1953；Al-Fares et al., SIGCOMM 2008 胖树整理</footer></div><p><a href="/cs/output-queue-hol">交换机 HOL</a> 与 <a href="/cs/ecmp-hashing">ECMP</a> 已备好。<a href="/cs/p4-programmable">上一课</a> 不改拓扑。缺口是<strong>数据中心怎么连</strong>：leaf-spine、过订购比、L3 到叶子。本课不把 incast 扇入写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接入–汇聚–核心树在东西向拥挤，STP 还要阻塞边。胖树/Clos：每叶子连所有脊，脊再可选超脊。带宽由「叶子上联数 × 口速」决定，过订购是刻意的经济。转发：每叶子一个子网，主机默认网关在叶子（IRB/EVPN），中间纯 L3 ECMP，无 STP 大域。VXLAN 覆盖跑在这张 IP 网上。</p><p>不要把 Clos 写成无阻塞的数学保证：流量矩阵一偏，脊仍可满。</p><p><span class="marginnote">Clos 原是电话交叉。Al-Fares 把胖树搬到以太网。本课不点名某云的内部名。</span></p><h3 id="东西向用-ecmp" tabindex="-1">东西向用 ECMP <a class="header-anchor" href="#东西向用-ecmp" aria-label="Permalink to &quot;东西向用 ECMP&quot;">​</a></h3><p>leaf-spine 多条等代价，大 STP 退出。过订购是经济，流量一偏脊仍满。故障重哈希会短暂乱序。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：leaf 与 spine 全网格。对照校园三层：这里每跳都 ECMP。LACP 可把多口当一条上联，但叶子到脊更常用独立 ECMP 边。</p>',11)),(e(),n(d,null,{default:l(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%B8%BB%E6%9C%BA%22%5D%20--%3E%20L%5B%22%E5%8F%B6%E5%AD%90%22%5D%0A%20%20L%20--%3E%20S1%5B%22%E8%84%8A%22%5D%0A%20%20L%20--%3E%20S2%5B%22%E8%84%8A%22%5D%0A%20%20S1%20--%3E%20L2%5B%22%E5%8F%A6%E4%B8%80%E5%8F%B6%E5%AD%90%22%5D%0A%20%20S2%20--%3E%20L2%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TE 在数据中心常简化为 ECMP + 尽量对称布线；极化仍在。BGP 可作 IGP（每盒一个 ASN 或私有 AS），收敛与策略比 OSPF 更熟——这是运营选择。5G 核心 UPF 也可落在 Clos 上，无线切片不改机房拓扑。</p><p>故障：一条脊挂了，哈希重映射，短暂乱序，与 LACP 成员 down 同类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Jupiter 一类专有细节。incast 是下一课。后课默认：东西向用 Clos + L3 ECMP，大 STP 退出。</p><p>光模块与 100G lane 决定实际能铺多少脊。</p><p>上一课留下的缺口在本课收口；「数据中心 Clos / 胖树」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/incast">incast</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>leaf-spine Clos 提供多条等代价东西向路径。</li><li>过订购是容量规划，不是协议字段。</li><li>用 ECMP 替代阻塞冗余边。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Clos, 1953；Al-Fares et al., 2008。</li></ul>',10))])}const S=o(h,[["render",C]]);export{A as __pageData,S as default};
